import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const deferred = new Map();
const feed = createProgressFeed({ initialPacket: 'initial', decode: packet => packet === 'initial' ? { n: 0 } : new Promise(resolve => deferred.set(packet, resolve)) });
const history = [], display = [], queue = [], notices = [], telemetry = [];
const stopTelemetry = collectProgressTelemetry(feed, frame => telemetry.push(frame));
const workspace = createTransferWorkspace({ transport() {}, onCancel() {}, record: x => queue.push(x), showQueued: x => notices.push(x), recordProgress: x => history.push(x), showProgress: x => display.push(x) });
const file = { id: 'a', progressFeed: feed };
const first = workspace.select(file);
assert.deepEqual(display.map(x => x.frame.n), [0]);
assert.equal(telemetry.length, 0);
feed.emit('old'); feed.emit('new');
deferred.get('new')({ n: 2 }); await Promise.resolve();
deferred.get('old')({ n: 1 }); await Promise.resolve();
assert.deepEqual(display.map(x => x.frame.n), [0, 2]);
assert.deepEqual(history.map(x => x.frame.n), [0, 2, 1]);
assert.deepEqual(telemetry.map(x => x.n), [2, 1]);
assert.deepEqual(queue, [{ fileId: 'a', attemptId: 1, visitId: 1, kind: 'select' }]);
first.cancel();
const second = workspace.select(file);
assert.deepEqual(display.map(x => x.frame.n), [0, 2, 0]);
second.cancel(); stopTelemetry();
const reentrantFeed = createProgressFeed({ initialPacket: 5 });
let reentrantWorkspace, cancelled = 0;
reentrantWorkspace = createTransferWorkspace({ transport() {}, onCancel() { cancelled++; }, record() {}, showQueued() {}, recordProgress() {}, showProgress() { reentrantWorkspace.hide(); } });
const reentrantHandle = reentrantWorkspace.select({ id: 'b', progressFeed: reentrantFeed });
assert.equal(reentrantHandle.signal.aborted, true);
assert.equal(cancelled, 1);
console.log('progress checks passed');
EOF"

